'use strict';

// MODULES //

var isArrayBuffer = require( '@stdlib/assert/is-arraybuffer' );
var isFunction = require( '@stdlib/assert/is-function' );
var isDataType = require( '@stdlib/ndarray/base/assert/is-data-type' );
var constructorFactory = require( '@stdlib/ndarray/tensor0d/ctor' ).factory;
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns a function for creating zero-dimensional ndarrays.
*
* @param {*} dtype - ndarray data type
* @param {*} defaultValue - default value
* @param {Function} isValidScalar - function for checking whether a value is a valid scalar value
* @throws {TypeError} first argument must be a valid data type
* @throws {TypeError} third argument must be a function
* @returns {Function} function for creating zero-dimensional ndarrays
*
* @example
* var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
*
* var Float64Tensor0D = factory( 'float64', 0.0, isNumber );
*
* var arr = new Float64Tensor0D();
* // returns <ndarray>[ 0.0 ]
*
* @example
* var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
*
* var Float64Tensor0D = factory( 'float64', 0.0, isNumber );
*
* var arr = new Float64Tensor0D( 1.0 );
* // returns <ndarray>[ 1.0 ]
*
* @example
* var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var Float64Tensor0D = factory( 'float64', 0.0, isNumber );
*
* var buf = new ArrayBuffer( 8 );
* var arr = new Float64Tensor0D( buf );
* // returns <ndarray>[ 0.0 ]
*
* @example
* var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var Float64Tensor0D = factory( 'float64', 0.0, isNumber );
*
* var buf = new ArrayBuffer( 16 );
* var arr = new Float64Tensor0D( buf, 8 );
* // returns <ndarray>[ 0.0 ]
*/
function factory( dtype, defaultValue, isValidScalar ) {
	var ctor;
	if ( !isDataType( dtype ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a supported data type. Value: `%s`.', dtype ) );
	}
	if ( !isFunction( isValidScalar ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a function. Value: `%s`.', isValidScalar ) );
	}
	ctor = constructorFactory( dtype );
	return Tensor0D;

	/**
	* Returns a zero-dimensional ndarray.
	*
	* @private
	* @param {(*|ArrayBuffer)} [value] - scalar or buffer
	* @param {NonNegativeInteger} [byteOffset=0] - byte offset
	* @param {Options} [options] - function options
	* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
	* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
	* @throws {TypeError} first argument must be either a buffer, options object, or a valid scalar value
	* @throws {TypeError} must provide valid options
	* @returns {ndarray} zero-dimensional ndarray
	*/
	function Tensor0D( value ) {
		var nargs = arguments.length;

		// Case: new Tensor0D()
		if ( nargs === 0 ) {
			return new ctor( defaultValue );
		}
		// Case: new Tensor0D( arg0 )
		if ( nargs === 1 ) {
			// Case: new Tensor0D( scalar|ArrayBuffer )
			if ( isValidScalar( value ) || isArrayBuffer( value ) ) {
				return new ctor( value );
			}
			// Case: new Tensor0D( options )
			return new ctor( defaultValue, value );
		}
		// Case: new Tensor0D( scalar|ArrayBuffer, arg1 )
		if ( nargs === 2 ) {
			if ( !isValidScalar( value ) && !isArrayBuffer( value ) ) {
				throw new TypeError( format( 'invalid argument. First argument must be either an ArrayBuffer or a valid scalar value. Value: `%s`.', value ) );
			}
			return new ctor( value, arguments[ 1 ] );
		}
		// Case: new Tensor0D( ArrayBuffer, byteOffset, options )
		return new ctor( value, arguments[ 1 ], arguments[ 2 ] );
	}
}


// EXPORTS //

module.exports = factory;
